window.AUTH=window.AUTH||{};window.AUTH["22-666"]={"d":"22-666","id":"2023/22-666","n":"Wilkinson v. Garland","briefs":[{"k":"petitioner","label":"Brief of petitioner Situ Kamu Wilkinson","date":"2023-08-29","url":"https://www.supremecourt.gov/DocketPDF/22/22-666/278461/20230829185728155_22-666%20Wilkinson%20v.%20Garland%20--%20Brief%20for%20Petitioner.pdf","side":"pet","n":73},{"k":"respondent","label":"Brief of respondent Garland, Attorney General of the United States","date":"2023-10-18","url":"https://www.supremecourt.gov/DocketPDF/22/22-666/285479/20231018181204435_22-666bsUnitedStates.pdf","side":"res","n":73},{"k":"reply","label":"Reply of petitioner Situ Kamu Wilkinson","date":"2023-11-17","url":"https://www.supremecourt.gov/DocketPDF/22/22-666/289933/20231117124130757_Wilkinson%20-%20Yellow%20Brief%20-%2017%20November%202023.pdf","side":"pet","n":54}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us1r10_k5fm.pdf","tr":true,"items":[{"t":"case","label":"Aguilar-Osorio v. Garland","cite":"991 F.3d 997","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/991/997/","op":1,"sum":"Holding that the court lacked jurisdiction to review hardship determinations without mentioning Guerrero-Lasprilla.","sumSrc":"brief:0","by":{"0":"34","1":"47"}},{"t":"case","label":"Alvarado v. Holder","cite":"743 F.3d 271","y":2014,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/743/271/","by":{"0":"42"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"0":"46","1":"2"}},{"t":"case","label":"Boechler, P.C. v. Comm’r of Internal Revenue","cite":"142 S. Ct. 1493","y":2022,"id":"2021/20-1472","sc":1,"sum":"The 30-day time limit to file a petition for review of a collection due process determination, 26 U. S. C. §6330(d)(1), is a nonjurisdictional deadline subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23"}},{"t":"case","label":"Bowen v. Mich. Acad. of Fam. Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Brown v. INS","cite":"775 F.2d 383","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/775/383/","by":{"0":"44"}},{"t":"case","label":"Castillo-Gutierrez v. Garland","cite":"43 F.4th 477","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/43/477/","op":1,"by":{"0":"34, 45"}},{"t":"case","label":"Chadha v. INS","cite":"634 F.2d 408","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/634/408/","by":{"0":"44","2":"23"}},{"t":"case","label":"Cooper Indus., Inc. v. Leatherman Tool Grp.","cite":"532 U.S. 424","y":2001,"id":"2000/99-2035","sc":1,"sum":"The Court held that the Courts of Appeals should apply a de novo standard when reviewing district court determinations of the constitutionality of punitive damages awards.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"ar":1,"sum":"Respondents, the defendants in a District Court suit instituted by petitioner law firm on behalf of a client, filed a motion to dismiss the complaint as having no basis in fact and a motion for sanctions under Federal Rule of Civil Procedure 11 on the ground that the firm had not made sufficient prefiling inquiries to support the complaint's allegations. Rule 11-after specifying, interalia, that an attorney's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","2":"15"}},{"t":"case","label":"Cortes-Castillo v. INS","cite":"997 F.2d 1199","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/997/1199/","by":{"0":"44"}},{"t":"case","label":"Dada v. Mukasey","cite":"554 U.S. 1","y":2008,"id":"2007/06-1181","sc":1,"sum":"Justice Anthony Kennedy, joined by four other Justices, stated that an alien has two options in such a case: he may abide by the terms of the voluntary departure and leave the country on time, maintaining the re-entry perks, or withdraw the voluntary departure request and remain in the country to pursue the motion to reopen. If the alien chooses the second option, he may become subject to deportation proceedings.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Direct Mktg. Ass’n v. Brohl","cite":"575 U.S. 1","y":2015,"id":"2014/13-1032","sc":1,"sum":"The Court held that the Tax Injunction Act does not prevent federal court review of state tax laws, unless such review could restrict the ability of the state to assess or collect its own taxes.","sumSrc":"Oyez","by":{"0":"3, 22, 38"}},{"t":"case","label":"Flores-Alonso v. U.S. Attorney General","cite":"36 F.4th 1095","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/36/1095/","op":1,"by":{"0":"33, 34, 38, 46"}},{"t":"case","label":"Foremost Ins. Co. v. Richardson","cite":"457 U.S. 668","y":1982,"id":"1981/80-2134","sc":1,"sum":"In light of the need for uniform rules governing navigation, the potential impact on maritime commerce when two vessels collide on navigable waters, and the uncertainty and confusion that would necessarily accompany a jurisdictional test tied to the commercial use of a given boat, a complaint alleging a collision between two vessels-including pleasure boats-on navigable waters properly states a claim within the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Galeano-Romero v. Barr","cite":"968 F.3d 1176","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/1176/","op":1,"sum":"Recognizing that, while hardship determinations are generally unreviewable, courts may consider claims that the Board engrafted an additional requirement onto the statutory text or otherwise misinterpreted it, as well as allegations that the agency failed to adhere to its precedents and regulations.","sumSrc":"brief:1","by":{"0":"33, 40, 48","1":"32, 47"}},{"t":"case","label":"Garcia-Pascual v. Garland","cite":"62 F.4th 1096","y":2023,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/62/1096/","sum":"Explaining that § 1252(a)(2)(D) “specifically allows us to consider constitutional questions and questions of law, even when a decision is a discretionary one”.","sumSrc":"brief:0","by":{"0":"35, 39, 47","1":"33"}},{"t":"case","label":"George v. McDonough","cite":"142 S. Ct. 1953","y":2022,"id":"2021/21-234","sc":1,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"44"}},{"t":"case","label":"Gitau v. Sessions","cite":"878 F.3d 429","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/878/429/","by":{"0":"39"}},{"t":"case","label":"Gonzalez Galvan v. Garland","cite":"6 F.4th 552","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/552/","op":2,"by":{"0":"34, 47"}},{"t":"case","label":"Google LLC v. Oracle Am., Inc.","cite":"141 S. Ct. 1183","y":2021,"id":"2020/18-956","sc":1,"sum":"Google’s limited copying of the Java SE Application Programming Interface allowed programmers to put their accrued talents to work in a transformative program and constituted a fair use of that material under copyright law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29","1":"19, 35, 36","2":"6"}},{"t":"case","label":"Grable & Sons Metal Prods., Inc. v. Darue Eng’g & Mfg.","cite":"545 U.S. 308","y":2005,"id":"2004/04-603","sc":1,"sum":"The Court held that the case involved a federal question and could thus be removed to federal court. Federal-questions jurisdiction, the Court reasoned, lay over some state-law claims that implicated significant federal issues. In this case, the national interest in providing a federal forum for federal tax litigation warranted moving the case to federal court.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Groff v. DeJoy","cite":"143 S. Ct. 2279","y":2023,"id":"2022/22-174","sc":1,"sum":"Title VII requires an employer that denies a religious accommodation to show that the burden of granting an accommodation would result in substantial increased costs in relation to the conduct of its particular business.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27","2":"12"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"op":34,"ar":22,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"0":"1, 2, 13, 17-18, 20-28, 31, 34-37, 41","1":"9, 12, 14, 16, 17, 23, 35","2":"1, 3, 4, 5, 15, 18, 20, 22"}},{"t":"case","label":"Harmelin v. Michigan","cite":"501 U.S. 957","y":1991,"id":"1990/89-7272","sc":1,"sum":"The Court, in a 5-to-4 decision, held that since the Eighth Amendment does not contain a proportionality guarantee, the determination of whether a punishment is \"cruel and unusual\" is not made with reference to the particular offense. Moreover, the Cruel and Unusual Punishment Clause protects against unusual methods of punishment, not necessarily cruel ones.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Hernandez v. Ashcroft","cite":"345 F.3d 824","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/345/824/","by":{"0":"38"}},{"t":"case","label":"Hernandez v. Garland","cite":"28 F.4th 917","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/28/917/","by":{"0":"39"}},{"t":"case","label":"Hernandez-Morales v. Attorney General","cite":"977 F.3d 247","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/977/247/","op":1,"sum":"Concluding that “a disagreement about weighing hardship factors is a discretionary judgment call, not a legal question,” but acknowledging that the agency would commit reviewable legal error by applying “ ‘an impermissible factor’ at odds with § 1229b(b)(1)(D)”.","sumSrc":"brief:1","by":{"0":"17, 33, 48, 51","1":"9, 32, 47"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"0":"22, 23, 38, 39, 42","2":"14"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"9","2":"23"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":3,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Jay v. Boyd","cite":"351 U.S. 345","y":1956,"id":"1955/503","sc":1,"sum":"The Attorney General has properly exercised his discretionary powers under the statute in this case, and denial of the application is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 46","1":"42, 43","2":"9, 21, 25"}},{"t":"case","label":"Kalaw v. INS","cite":"133 F.3d 1147","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/1147/","by":{"0":"51"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"21, 36, 49"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"sum":"The Court held that judicial review of the Equal Employment Opportunity Commission’s efforts at conciliation is appropriate, but such review must be limited to the narrow requirements that Title VII imposes.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Martinez v. Clark","cite":"36 F.4th 1219","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/36/1219/","by":{"0":"33, 38, 48"}},{"t":"case","label":"McNary v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"sum":"The District Court had federal-question jurisdiction to hear respondents' constitutional and statutory challenges to the INS procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Mendez-Castro v. Mukasey","cite":"552 F.3d 975","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/552/975/","by":{"0":"38, 40"}},{"t":"case","label":"Mendez-Moranchel v. Ashcroft","cite":"338 F.3d 176","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/338/176/","by":{"0":"51"}},{"t":"case","label":"Miller v. Fenton","cite":"474 U.S. 104","y":1985,"id":"1985/84-5786","sc":1,"sum":"The voluntariness of a confession is not an issue of fact entitled to the §2254(d) presumption but is a legal question meriting independent consideration in a federal habeas corpus proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","1":"35, 36","2":"6"}},{"t":"case","label":"41, 43, 44, 47 Morales Ventura v. Ashcroft","cite":"348 F.3d 1259","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/348/1259/","op":1,"by":{"0":"33, 48"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"572 U.S. 545","y":2014,"id":"2013/12-1184","sc":1,"ar":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"0":"27","1":"20, 21, 25, 29","2":"18"}},{"t":"case","label":"Ornelas v. United States","cite":"517 U.S. 690","y":1996,"id":"1995/95-5257","sc":1,"op":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held \"[t]he ultimate questions of reasonable suspicion and probable cause to make a warrantless search should be reviewed de novo.\" The principle details in such a review should be an analysis of events leading up to the search and the objective review of the search.","sumSrc":"Oyez","by":{"0":"28, 29","2":"11"}},{"t":"case","label":"Patel v. Garland","cite":"142 S. Ct. 1614","y":2022,"id":"2021/20-979","sc":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"11, 13, 26, 27, 35, 37, 45, 50, 46, 49, 50","1":"9, 12-18, 21, 22, 29, 32-34, 41, 42, 46","2":"3, 7, 20, 22, 25"}},{"t":"case","label":"Pereida v. Wilkinson","cite":"141 S. Ct. 754","y":2021,"id":"2020/19-438","sc":1,"sum":"A nonpermanent resident seeking to cancel a lawful removal order fails to carry his burden of showing that he has not been convicted of a disqualifying offense when the statutory conviction on his record is ambiguous regarding whether a disqualifying offense formed the basis of his conviction.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"46"}},{"t":"case","label":"Ponce Flores v. U.S. Attorney General","cite":"64 F.4th 1208","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/64/1208/","by":{"0":"33","1":"32, 47"}},{"t":"case","label":"Pullman-Standard v. Swint","cite":"456 U.S. 273","y":1982,"id":"1981/80-1190","sc":1,"op":1,"ar":3,"sum":"The Court of Appeals erred in the course of its review of the District Court's judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","1":"10, 15, 19, 20, 21, 34, 39","2":"6"}},{"t":"case","label":"Ray Haluch Gravel Co. v. Central Pension Fund of Int’l Union of Operating Eng’rs & Participating Emp’rs","cite":"571 U.S. 177","y":2014,"id":"2013/12-992","sc":1,"sum":"The Court held that a district court's decision on a case based on merit is a \"final answer\" in terms of an eventual appeal.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Romero-Torres v. Ashcroft","cite":"327 F.3d 887","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/327/887/","sum":"Explaining that when evaluating cancellation’s “good moral character” eligibility criterion, the court “had jurisdiction to decide whether the applicant fell into per se exclusion categories, such as habitual drunkenness or conviction of a felony” but “lacked jurisdiction to consider the question apart from these categories” because “good moral character is almost necessarily a subjective question” (citation omitted).","sumSrc":"brief:0","by":{"0":"33, 42, 47, 48"}},{"t":"case","label":"Ruiz v. U.S. Attorney General","cite":"73 F.4th 852","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/73/852/","by":{"0":"39"}},{"t":"case","label":"Santos v. Holder","cite":"573 F. App’x 634","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/573/634/","ar":4,"by":{"0":"38"}},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"sum":"The Court ruled 8-1 that Scott's actions were reasonable under the Fourth Amendment. The opinion by Justice Antonin Scalia relied heavily on a videotape of the car chase, which it said contradicted the plaintiff's claim that he was driving responsibly even while being pursued by the police.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Shalala v. Ill. Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"sum":"The Court held that the Medicare Act barred federal-question jurisdiction of the Council's challenges to the validity of various Medicare regulations. The Court concluded that the Council must proceed instead through the special review channel that the Medicare statutes create.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Singh v. Rosen","cite":"984 F.3d 1142","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/984/1142/","op":1,"by":{"0":"31, 34, 45, 47"}},{"t":"case","label":"50, 51 Sisson v. Ruby","cite":"497 U.S. 358","y":1990,"id":"1989/88-2041","sc":1,"sum":"The Court held that the district court has maritime jurisdiction when the incident in question represents a potential hazard to maritime commerce and bears a substantial relationship to maritime activity.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Small v. Memphis Light, Gas & Water","cite":"141 S. Ct. 1227","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/1227/","sc":1,"by":{"0":"28"}},{"t":"case","label":"Tacuri-Tacuri v. Garland","cite":"998 F.3d 466","y":2021,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/998/466/","by":{"0":"42"}},{"t":"case","label":"Teva Pharms. USA, Inc. v. Sandoz, Inc.","cite":"574 U.S. 318","y":2015,"id":"2014/13-854","sc":1,"ar":1,"sum":"The Court ruled that a federal appellate court can only overturn a district court’s finding of fact if those findings were determined to be “clearly erroneous.”","sumSrc":"Oyez","by":{"0":"29","1":"47"}},{"t":"case","label":"Thompson v. Keohane","cite":"516 U.S. 99","y":1995,"id":"1995/94-6615","sc":1,"sum":"State-court \"in custody\" rulings, made to determine whether Mirandawarnings are due, do not qualify for a presumption of correctness under §2254(d). Such rulings do not resolve \"a factual issue.\" Instead, they resolve mixed questions of law and fact and therefore warrant independent review by the federal habeas court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Thryv, Inc v. Click-To-Call Techs., LP","cite":"140 S. Ct. 1367","y":2020,"id":"2019/18-916","sc":1,"sum":"The Court held that 35 U.S.C. §314(d) precludes judicial review of a Patent Trial and Appeal Board’s decision to institute inter partes review upon finding that §315(b)’s time bar did not apply.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Tobar-Bautista v. Sessions","cite":"710 F. App’x 506","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/710/506/","by":{"0":"47"}},{"t":"case","label":"Trejo v. Garland","cite":"3 F.4th 760","y":2021,"url":"https://www.courtlistener.com/c/F.4th/3/760/","by":{"0":"45, 50, 51, 52"}},{"t":"case","label":"Twum v. Barr","cite":"930 F.3d 10","y":2019,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/930/10/","by":{"0":"39"}},{"t":"case","label":"Valenzuela Alcantar v. INS","cite":"309 F.3d 946","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/946/","by":{"0":"48"}},{"t":"law","label":"Pub. L. No. 80-863","by":{"0":"9"}},{"t":"law","label":"Pub. L. No. 87-885","url":"https://www.govinfo.gov/link/statute/76/1247","by":{"0":"9, 10","1":"3"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"10","1":"2"}},{"t":"law","label":"Pub. L. No. 82-414","url":"https://www.govinfo.gov/link/statute/66/163","by":{"0":"9, 44, 50"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(9)(B)(v)","(d)(12)(B)","(h)(1)(B)","(i)(1)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"50","2":"19, 24, 24"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"5"}},{"t":"reg","label":"8 C.F.R. § 1003.1","url":"https://www.ecfr.gov/current/title-8/section-1003.1","subs":["(d)(3)(i)"],"by":{"0":"6","2":"7"}},{"t":"case","label":"Adeyeye v. Heartland Sweeteners, LLC","cite":"721 F.3d 444","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/721/444/","sum":"Holding that district court erred in granting summary judgment on “undue hardship” under Title VII because the determination presented questions of fact that should have been put before a jury.","sumSrc":"brief:1","by":{"1":"38"}},{"t":"case","label":"Amgen Inc. v. Sanofi","cite":"598 U.S. 534","y":2023,"id":"2022/21-757","sc":1,"sum":"Amgen’s two patent applications—purporting to cover all antibodies that bind and block the PCSK9 receptor involved in LDL cholesterol metabolism—fail to satisfy the Patent Act’s enablement clause, see 35 U. S. C. §112(a).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"sum":"The effective date of an award of service-related disability compensation to a veteran of the United States military determined pursuant to 38 U. S. C. §§5110(a)(1) and 5110(b)(1) is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Berkovitz v. United States","cite":"486 U.S. 531","y":1988,"id":"1987/87-498","sc":1,"sum":"A provision of the Federal Tort Claims Act (FTCA) excepts from statutory liability any claim \"based upon [a federal agency's or employee's] exercise or performance or the failure to exercise or perform a discretionary function or duty.\" Upon contracting a severe case of polio after ingesting a dose of Orimune, an oral polio vaccine manufactured by Lederle Laboratories, petitioner Kevan Berkovitz, a minor, joined by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22","2":"8"}},{"t":"case","label":"Bose Corp. v. Consumers Union of U.S., Inc.","cite":"466 U.S. 485","y":1984,"id":"1983/82-1246","sc":1,"sum":"The Court held that while the record revealed that the article's author mistakenly described the sound path of Bose speakers, he did not do so with actual malice.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Commissioner v. Duberstein","cite":"363 U.S. 278","y":1960,"id":"1959/376","sc":1,"ar":1,"sum":"On the record in this case, it cannot be said COMMISSIONER v. DUBERSTEIN..278","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 21, 29"}},{"t":"case","label":"Concepcion v. United States","cite":"142 S. Ct. 2839","y":2022,"id":"2021/20-1650","sc":1,"sum":"Section 404(b) of the First Step Act of 2018, 132 Stat. 5222, allows district courts to consider intervening changes of law or fact in exercising their discretion to reduce a sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"43"}},{"t":"case","label":"Dupree v. Younger","cite":"598 U.S. 729","y":2023,"id":"2022/22-210","sc":1,"sum":"A post-trial motion under Federal Rule of Civil Procedure 50 is not required to preserve for appellate review a purely legal issue resolved at summary judgment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"47"}},{"t":"case","label":"Gonzalez-Rivas v. Garland","cite":"53 F.4th 1129","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/53/1129/","op":1,"by":{"1":"47"}},{"t":"case","label":"Hernandez-Cordero v. INS","cite":"819 F.2d 558","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/558/","by":{"1":"28"}},{"t":"case","label":"Hiatt v. Brown","cite":"339 U.S. 103","y":1950,"id":"scdb/1949-052","sc":1,"sum":"Respondent, a soldier in the United States Army in Germany, was convicted of murder by a general court-martial and was sentenced to imprisonment. At the time of the trial, in 1947, the 8th Article of War required the authority appointing a general court-martial to detail as law member thereof an officer of the Judge Advocate General's Department, except when an officer of that department was \"not available for the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Highmark Inc. v. Allcare Health Mgmt. Sys., Inc.","cite":"572 U.S. 559","y":2014,"id":"2013/12-1163","sc":1,"sum":"The Court held that a district court is the best place to determine whether or not a lawsuit is objectively baseless.","sumSrc":"Oyez","by":{"1":"18, 20, 43","2":"9, 18"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"INS v. Hector","cite":"479 U.S. 85","y":1986,"id":"1986/86-21","sc":1,"sum":"The Board is not required under §244(a)(1) to consider the hardship to a third party other than a spouse, parent, or child, as defined by the Act. The definition of the term \"child\" in § 101(b)(1) of the Act is particularly exhaustive. Even if respondent's relationship with her nieces closely resembles a parent-child relationship, Congress, through the statute's plain language, precluded the functional approach to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27, 28, 44"}},{"t":"case","label":"INS v. Jong Ha Wang","cite":"450 U.S. 139","y":1981,"id":"1980/80-485","sc":1,"ar":1,"sum":"The Board did not exceed its authority and the Court of Appeals erred in ordering that the case be reopened. Respondents' allegations of hardship were in the main conclusory and unsupported by affidavit, as required by the applicable regulations. Moreover, the Court of Appeals improvidently encroached on the authority which the Act confers on the Attorney General and his delegates to define \"extreme hardship\" in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27, 37","2":"23, 24"}},{"t":"case","label":"INS v. Orlando Ventura","cite":"537 U.S. 12","y":2002,"id":"2002/02-29","sc":1,"sum":"The Court held that an appellate court should generally remand a case to an agency when the subject matter is one over which the agency has authority pursuant to a statute.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"INS v. Phinpathya","cite":"464 U.S. 183","y":1984,"id":"1983/82-91","sc":1,"sum":"The Court held that the “continuous physical presence” requirement for suspension of deportation in the Immigration and Nationality Act should be interpreted literally.","sumSrc":"Oyez","by":{"1":"27","2":"21, 22, 23, 24"}},{"t":"case","label":"Karlin v. Reed","cite":"584 F.2d 365","y":1978,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/584/365/","sum":"Describing courts’ treatment of hardship determinations in connection with military staffing as discretionary.","sumSrc":"brief:1","by":{"1":"38"}},{"t":"case","label":"Kimbro v. Atlantic Richfield Co.","cite":"889 F.2d 869","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/889/869/","by":{"1":"38"}},{"t":"case","label":"Liu v. United States Dep’t of Justice","cite":"13 F.3d 1175","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/13/1175/","by":{"1":"28"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"McWright v. Alexander","cite":"982 F.2d 222","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/982/222/","by":{"1":"38"}},{"t":"case","label":"Metropolitan Stevedore Co. v. Rambo","cite":"521 U.S. 121","y":1997,"id":"1996/96-272","sc":1,"sum":"The Court held that nominal compensation is proper when there is a significant possibility that the worker's wage-earning capacity will fall below the level of his pre-injury wages sometime in the future.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Moog Indus. Inc. v. Federal Trade Commission","cite":"355 U.S. 411","y":1958,"id":"1957/77","sc":1,"sum":"The question whether a valid order of the Federal Trade Commission, directing one firm to cease and desist from engaging in illegal price discrimination in violation of § 2 of the Clayton Act, should go into effect before competing firms are similarly restrained is for deter mination by the Commission; it should be considered by a reviewing court only if raised before the Commission; and a deternination of it by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22","2":"8"}},{"t":"case","label":"Perez v. Garland","cite":"67 F.4th 254","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/67/254/","by":{"1":"32"}},{"t":"case","label":"Ramirez-Durazo v. INS","cite":"794 F.2d 491","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/794/491/","sum":"Finding case was “devoid of those unique extenuating circumstances necessary” to satisfy the abuse-of-discretion standard.","sumSrc":"brief:1","by":{"1":"28"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"1":"3, 28"}},{"t":"case","label":"SEC v. Central-Ill. Sec. Corp.","cite":"338 U.S. 96","y":1949,"id":"scdb/1948-120","sc":1,"sum":"The Commission's approval of the plan was not contrary to law; its findings were supported by adequate evidence; and its order should have been approved and enforced. Pp. 99-113, 155.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Turri v. INS","cite":"997 F.3d 1306","y":1993,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/1306/","by":{"1":"28"}},{"t":"case","label":"U.S. Bank Nat’l Ass’n v. Village at Lakeridge, LLC","cite":"138 S. Ct. 960","y":2018,"id":"2017/15-1509","sc":1,"op":2,"sum":"The Court held that a designation of non-statutory insider status is reviewable under the standard of clear error because the \"mixed question\" of law and fact at issue is primarily factual.","sumSrc":"Oyez","by":{"1":"18, 21","2":"5, 11, 15"}},{"t":"case","label":"United States v. Yellow Cab Co.","cite":"338 U.S. 338","y":1949,"id":"scdb/1949-016","sc":1,"sum":"Judgment affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Wainwright v. Witt","cite":"469 U.S. 412","y":1985,"id":"1984/83-1427","sc":1,"sum":"Respondent was tried by a jury in a Florida state court and convicted of first-degree murder. In accordance with the jury's recommendation, he was sentenced to death. On appeal, respondent claimed that several prospective jurors had been improperly excluded for cause because of their opposition to capital punishment, in violation of the decision in Witherspoon v. Illinois, 391 U. S. 510, but the Florida Supreme …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Weyerhauser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"44","2":"9"}},{"t":"case","label":"Williamsport Wire Rope Co. v. United States","cite":"277 U.S. 551","y":1928,"id":"scdb/1927-126","sc":1,"op":4,"ar":5,"sum":"1. The power of the Commissioner of Internal Revenue in determining whether a corporation is entitled, under § 327 (a) and (b) of the Revenue Act of 1918, to have its war and excess profits taxes fixid by a special assessment under § 328 by a comparison with the taxes of other, representative corporations engaged in a like or similar trade or business, is discretionary in character; and the power of the Board of Tax …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10, 15, 22, 23, 25, 26, 30","2":"11, 13, 16, 17"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"1":"31"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)"],"by":{"1":"44"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"1":"44"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"1":"15, 20, 37-39"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(h)"],"by":{"1":"15"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)"],"by":{"1":"2, 2"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)(1)(B)(iii)"],"by":{"1":"15"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(c)(4)(A)","(c)(4)(C)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"head":"§1229a. Removal proceedings","tname":"Aliens and Nationality","by":{"1":"4, 15","2":"25"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(b)(1)","(b)(1)(D)","(b)(1)(B)"],"stext":{"head":"§1229b. Cancellation of removal; adjustment of status","paras":[[0,"(a) Cancellation of removal for certain permanent residents"],[0,"The Attorney General may cancel removal in the case of an alien who is inadmissible or deportable from the United States if the alien—"],[1,"(1) has been an alien lawfully admitted for permanent residence for not less than 5 years,"],[1,"(2) has resided in the United States continuously for 7 years after having been admitted in any status, and"],[1,"(3) has not been convicted of any aggravated felony."],[0,"(b) Cancellation of removal and adjustment of status for certain nonpermanent residents"],[0,"(1) In general"],[1,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien—"],[2,"(A) has been physically present in the United States for a continuous period of not less than 10 years immediately preceding the date of such application;"],[2,"(B) has been a person of good moral character during such period;"],[2,"(C) has not been convicted of an offense under section 1182(a)(2), 1227(a)(2), or 1227(a)(3) of this title, subject to paragraph (5); and"],[2,"(D) establishes that removal would result in exceptional and extremely unusual hardship to the alien's spouse, parent, or child, who is a citizen of the United States or an alien lawfully admitted for permanent residence."],[0,"(2) Special rule for battered spouse or child"],[0,"(A) Authority"],[2,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien demonstrates that—"],[3,"(i)(I) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a United States citizen (or is the parent of a child of a United States citizen and the child has been battered or subjected to extreme cruelty by such citizen parent);"],[3,"(II) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a lawful permanent resident (or is the parent of a child of an alien who is or was a lawful permanent resident and the child has been battered or subjected to extreme cruelty by such permanent resident parent); or"],[3,"(III) the alien has been battered or subjected to extreme cruelty by a United States citizen or lawful permanent resident whom the alien intended to marry, but whose marriage is not legitimate because of that United States citizen's or lawful permanent resident's bigamy;"],[3,"(ii) the alien has been physically present in the United States for a continuous period of not less than 3 years immediately preceding the date of such application, and the issuance of a charging document for removal proceedings shall not toll the 3-year period of continuous physical presence in the United States;"],[3,"(iii) the alien has been a person of good moral character during such period, subject to the provisions of subparagraph (C);"],[3,"(iv) the alien is not inadmissible under paragraph (2) or (3) of section 1182(a) of this title, is not deportable under paragraphs (1)(G) or (2) through (4) of section 1227(a) of this title, subject to paragraph (5), and has not been convicted of an aggravated felony; and"],[3,"(v) the removal would result in extreme hardship to the alien, the alien's child, or the alien's parent."],[0,"(B) Physical presence"],[2,"Notwithstanding subsection (d)(2), for purposes of subparagraph (A)(ii) or for purposes of section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), an alien shall not be considered to have failed to maintain continuous physical presence by reason of an absence if the alien demonstrates a connection between the absence and the battering or extreme cruelty perpetrated against the alien. No absence or portion of an absence connected to the battering or extreme cruelty shall count toward the 90-day or 180-day limits established in subsection (d)(2). If any absence or aggregate absences exceed 180 days, the absences or portions of the absences will not be considered to break the period of continuous presence. Any such period of time excluded from the 180-day limit shall be excluded in computing the time during which the alien has been physically present for purposes of the 3-year requirement set forth in this subparagraph, subparagraph (A)(ii), and section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(C) Good moral character"],[2,"Notwithstanding section 1101(f) of this title, an act or conviction that does not bar the Attorney General from granting relief under this paragraph by reason of subparagraph (A)(iv) shall not bar the Attorney General from finding the alien to be of good moral character under subparagraph (A)(iii) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), if the Attorney General finds that the act or conviction was connected to the alien's having been battered or subjected to extreme cruelty and determines that a waiver is otherwise warranted."],[0,"(D) Credible evidence considered"],[2,"In acting on applications under this paragraph, the Attorney General shall consider any credible evidence relevant to the application. The determination of what evidence is credible and the weight to be given that evidence shall be within the sole discretion of the Attorney General."],[0,"(3) Recordation of date"],[1,"With respect to aliens who the Attorney General adjusts to the status of an alien lawfully admitted for permanent residence under paragraph (1) or (2), the Attorney General shall record the alien's lawful admission for permanent residence as of the date of the Attorney General's cancellation of removal under paragraph (1) or (2)."],[0,"(4) Children of battered aliens and parents of battered alien children"],[0,"(A) In general"],[2,"The Attorney General shall grant parole under section 1182(d)(5) of this title to any alien who is a—"],[3,"(i) child of an alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996); or"],[3,"(ii) parent of a child alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(B) Duration of parole"],[2,"The grant of parole shall extend from the time of the grant of relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to the time the application for adjustment of status filed by aliens covered under this paragraph has been finally adjudicated. Applications for adjustment of status filed by aliens covered under this paragraph shall be treated as if the applicants were VAWA self-petitioners. Failure by the alien granted relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to exercise due diligence in filing a visa petition on behalf of an alien described in clause (i) or (ii) may result in revocation of parole."],[0,"(5) Application of domestic violence waiver authority"],[1,"The authority provided under section 1227(a)(7) of this title may apply under paragraphs (1)(B), (1)(C), and (2)(A)(iv) in a cancellation of removal and adjustment of status proceeding."],[0,"(6) Relatives of trafficking victims"],[0,"(A) In general"],[2,"Upon written request by a law enforcement official, the Secretary of Homeland Security may parole under section 1182(d)(5) of this title any alien who is a relative of an alien granted continued presence under section 7105(c)(3)(A) of title 22, if the relative—"],[3,"(i) was, on the date on which law enforcement applied for such continued presence—"],[4,"(I) in the case of an alien granted continued presence who is under 21 years of age, the spouse, child, parent, or unmarried sibling under 18 years of age, of the alien; or"],[4,"(II) in the case of an alien granted continued presence who is 21 years of age or older, the spouse or child of the alien; or"],[3,"(ii) is a parent or sibling of the alien who the requesting law enforcement official, in consultation with the Secretary of Homeland Security, as appropriate, determines to be in present danger of retaliation as a result of the alien's escape from the severe form of trafficking or cooperation with law enforcement, irrespective of age."],[0,"(B) Duration of parole"],[0,"(i) In general"],[3,"The Secretary may extend the parole granted under subparagraph (A) until the final adjudication of the application filed by the principal alien under section 1101(a)(15)(T)(ii) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229b?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1229b. Cancellation of removal; adjustment of status","tname":"Aliens and Nationality","by":{"1":"13, 45, 2, 5, 8, 10-13, 23, 25","2":"18, 25"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(a)(2)","(a)(2)(B)","(a)(2)(B)(i)","(a)(2)(D)","(a)(2)(B)(ii)","(b)(9)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"1":"4, 4, 9, 4, 13, 28, 5, 9, 12-18, 31, 33-35, 41, 42, 44-47, 4, 5, 9, 10, 12-14, 17, 18, 23, 29, 31-33, 42, 43, 45, 46","2":"19, 19, 20, 24, 19, 14, 19, 20, 4, 5"}},{"t":"usc","label":"8 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/8/1254","subs":["(a)(1)(1964)","(a)(2)(1964)"],"by":{"1":"3, 3, 27"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"1":"4"}},{"t":"case","label":"Antoine-Dorcelli v. INS","cite":"703 F.2d 19","y":1983,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/703/19/","by":{"2":"24"}},{"t":"case","label":"Blanco v. INS","cite":"68 F.3d 642","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/68/642/","by":{"2":"24"}},{"t":"case","label":"Buffalo Courier-Express, Inc. v. Buffalo Evening News, Inc.","cite":"601 F.2d 48","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/601/48/","by":{"2":"8"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Nat. Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"ar":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"City of Escondido v. Emmons","cite":"139 S. Ct. 500","y":2019,"id":"2018/17-1660","sc":1,"sum":"The Ninth Circuit failed to conduct the analysis required by this Court’s precedents in determining whether two Escondido police officers were entitled to qualified immunity.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"17"}},{"t":"case","label":"Graham v. Florida","cite":"560 U.S. 48","y":2010,"id":"2009/08-7412","sc":1,"sum":"The Court found that a non-homicidal conviction leading to a life sentence without parole for a juvenile violates the Eighth Amendment.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Hernandez-Patino v. INS.","cite":"831 F.2d 750","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/831/750/","by":{"2":"24"}},{"t":"case","label":"Maslenjak v. United States","cite":"582 U.S. 335","y":2017,"id":"2016/16-309","sc":1,"sum":"The Court determined that, for a naturalized American citizen to be stripped of her citizenship, the government has to prove that she obtained her citizenship illegally; if the underlying illegality is a false statement to government officials, the government must prove that the false statement influenced the citizenship process.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"McLane Co. v. EEOC","cite":"581 U.S. 72","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/72/","sc":1,"by":{"2":"8, 9, 10"}},{"t":"case","label":"Metlyn Realty Corp. v. Esmark, Inc.","cite":"763 F.2d 826","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/763/826/","by":{"2":"8"}},{"t":"case","label":"Nkomo v. Attorney General","cite":"986 F.3d 268","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/986/268/","by":{"2":"12"}},{"t":"case","label":"Patel v. U.S. Attorney General","cite":"971 F.3d 1258","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/971/1258/","by":{"2":"9"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Sandin v. Conner","cite":"515 U.S. 472","y":1995,"id":"1994/93-1911","sc":1,"sum":"Neither the Hawaii prison regulation nor the Due Process Clause itself affords Conner a protected liberty interest that would entitle him to the procedural protections set forth in Wolff.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Seaboard Air Line Ry. v. United States","cite":"254 U.S. 57","y":1920,"id":"scdb/1920-044","sc":1,"sum":"A diserimmatioii between shippers, in charges for transportation; otherwise violative of § 2 of the Act to Regulate Commerce, cannot be justified by.the exigencies of competition between carriers. P. 62. Wight v. United States, 167 U. S. *512.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"16"}},{"t":"usc","label":"8 U.S.C. § 1186a","url":"https://www.law.cornell.edu/uscode/text/8/1186a","subs":["(c)(4)(B)","(c)(4)(C)","(c)(4)(D)"],"by":{"2":"18, 18, 18"}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(l)"],"by":{"2":"24"}},{"t":"usc","label":"35 U.S.C. § 285","url":"https://www.law.cornell.edu/uscode/text/35/285","by":{"2":"18"}}]};